    for name, d in order:
        text = m.group(name)
        if d == "Y":
            year = int(text)
        elif d == "y":
            year = 2000 + int(text)
        elif d in ("m",):
            month = int(text)
        elif d == "d":
            day = int(text)
        elif d == "b":
            month = _MONTHS.index(text.lower()) + 1
        else:
            month = _MONTH_NAMES.index(text.lower()) + 1
